  /** A valid initialize request found no common version; block commands until a compatible retry or shutdown. */
  private unsupportedProtocol?: string;

  constructor(options: SidecarOptions) {
    this.app = options.app;
    this.write = options.write;
    const config = this.app.getConfig();
    this.mode = options.mode ?? config.approvalMode ?? (config.readOnly ? "read-only" : config.fullAccess ? "auto" : "review");
    this.app.getAgent().setApprovalMode(this.mode);
    this.onShutdown = options.onShutdown ?? (() => {});
    this.resume = options.resume;
    this.fullHistoryReplay = options.fullHistoryReplay ?? false;
    this.sessionId = this.app.getSessionManager().generateSessionId();
    } catch (err) {
      this.emit({ type: "error", id, code: "INTERNAL", message: errorText(err) });
    }
  }

  private slashHost(id: string): SlashHost {
    return {
      app: this.app,
      mode: () => this.app.getAgent().getApprovalMode(),
      setMode: (mode) => {
        this.mode = mode as ApprovalMode;
        this.app.getAgent().setApprovalMode(this.mode);
        if (this.mode !== "auto") this.alwaysApprove = false;
        this.emitSessionState();
      },
      sessionId: () => this.sessionId,
  }

  public setApprovalMode(mode: ApprovalMode): void {
    // GV-1: a mode that managed policy disables is not entered at runtime (`/mode auto`, an "always" answer). The mode
    // stays as it is and the operator is told which policy decided; the call being approved is not affected.
    const clamp = clampRuntimeApprovalMode(this.bridge?.getSecurityManager().getEffectivePolicy() ?? managedPolicy(), this.config.approvalMode ?? "review", mode, "A request for approval mode 'auto'");
    if (clamp.notice) {
      if (this.observer?.onNotice) this.observer.onNotice(`[nexus] ${clamp.notice}`);
      else console.warn(`[nexus] ${clamp.notice}`);
      return;
    }
    // Read-only selected at runtime is a mode choice, not an explicit launch invariant: record that so a later
    // /mode auto or /mode review can deliberately leave it, exactly like --mode read-only.
    if (mode === "read-only" && !this.config.readOnly && !this.config.readOnlyModeSelected) {
      this.config.readOnlyModeSelected = true;
    }
    // config.readOnly is the configured (launch or deliberate mode) posture. The checkpoint fallback is transient
    // and must never leak into it, or releasing the fallback could never restore the operator's mode.
    const configuredReadOnly = this.modeReadOnly(mode);
    this.config.approvalMode = mode;
    this.config.readOnly = configuredReadOnly;
    this.config.fullAccess = mode === "auto" ? this.configuredFullAccess : false;
    this.applyReadOnlyAuthority(this.checkpointReadOnlyFallback || configuredReadOnly);
    this.clearApprovedEgressOrigins();
    this.clearApprovedVerifiers();
  }
  // Run only while no turn is active (a host queues /compact during a turn: AutonomousAgent.requestCompaction).
  const result = await host.app.getAgent().compactNow(args.split(/\s+/).includes("--llm"), signal);
  return reply("compact", result.message, result.ok);
}

function mode({ host, args }: SlashContext): SlashOutcome {
  const wanted = args.trim().toLowerCase();
  if (wanted === "auto" || wanted === "autonomous") {
    host.setMode("auto");
    // GV-1: a mode managed policy disables was not entered; say so, with the policy source, instead of "Mode: auto".
    const refused = clampRuntimeApprovalMode(host.app.getAgent().getBridge().getSecurityManager().getEffectivePolicy(), host.mode(), "auto", "/mode auto").notice;
    if (refused) return reply("mode", refused, false);
    if (host.mode() === "read-only") return reply("mode", "Mode: read-only. Auto mode will take effect after a safe workspace checkpoint.");
    return reply("mode", "Mode: auto. Edits and commands run without asking.");
  }
  if (request.fullAccessOrigin !== undefined && noFull.value) return refuse(`${request.fullAccessOrigin} is refused: managed policy disables full access.`, noFull.source);
  return { allowed: true, value: { mode: request.mode, fullAccess: request.fullAccessOrigin !== undefined }, source: request.mode === "auto" ? noAuto.source : noFull.source };
}

/** A mode change asked for during a session (`/mode auto`): the mode to use. A disabled mode leaves the current one, with a notice. */
export function clampRuntimeApprovalMode(policy: EffectivePolicy, current: RequestedApprovalMode, requested: RequestedApprovalMode, origin: string): { mode: RequestedApprovalMode; changed: boolean; notice?: string; source: PolicySource } {
  const noAuto = policy.approval.disable_auto;
  if (requested === "auto" && noAuto.value) {
    return { mode: current, changed: false, notice: `${origin} is ignored: managed policy disables approval mode 'auto'; the mode stays '${current}'. ${describeSource(noAuto.source)}`, source: noAuto.source };
  }
  return { mode: requested, changed: requested !== current, source: noAuto.source };
}

/** An "always" answer to an approval prompt: whether it may be remembered. When it may not, the one call is still approved. */
export function clampAlwaysApproval(policy: EffectivePolicy): { remember: boolean; approveThisCall: true; notice?: string; source: PolicySource } {
  const noAuto = policy.approval.disable_auto;
  if (!noAuto.value) return { remember: true, approveThisCall: true, source: noAuto.source };
  return { remember: false, approveThisCall: true, notice: `'always' is not remembered: managed policy disables approval mode 'auto'; this one call is approved. ${describeSource(noAuto.source)}`, source: noAuto.source };
}

/** Whether `effect` needs a human decision whatever the approval mode, full access included. */
export function requiresHuman(policy: EffectivePolicy, effect: HumanEffect): { required: boolean; message?: string; source: PolicySource } {
  const item = policy.approval.require_human.items.find((i) => i.value === effect);
  if (!item) return { required: false, source: defaultSource("approval.require_human") };
  return { required: true, message: `approval required: managed policy requires a human decision for ${effect}, also under full access. ${describeSource(item.source)}`, source: item.source };
}

export interface SandboxRequest {
  /** The sandbox the operator asked for: a backend name, `none`, or undefined when nothing was asked. */
  mode: string | undefined;
  /** What asked, as the operator wrote it: `--sandbox none`. */

